export class AppService extends pulumi.ComponentResource {
  public readonly url: pulumi.Output<string>;
  public readonly serviceArn: pulumi.Output<string>;

  constructor(name: string, args: AppServiceArgs, opts?: pulumi.ComponentResourceOptions) {
    super("myplatform:index:AppService", name, {}, opts);
    const childOpts = { parent: this };

    const taskDef = new aws.ecs.TaskDefinition(`${name}-task`, { ... }, childOpts);
    const service  = new aws.ecs.Service(`${name}-svc`, {
      taskDefinition: taskDef.arn,
      ...
    }, childOpts);

    this.serviceArn = service.id;
    this.url = pulumi.interpolate`https://${lb.dnsName}`;
    this.registerOutputs({ url: this.url, serviceArn: this.serviceArn });
  }
}

