const dnsProvider: pulumi.dynamic.ResourceProvider = {
  async create(inputs) {
    const existing = await dnsApi.get(inputs.name).catch(() => null);
    if (existing) return { id: existing.id, outs: { ...existing } };
    const record = await dnsApi.create(inputs);
    return { id: record.id, outs: { ttl: record.ttl, value: record.value } };
  },
  async diff(id, olds, news) {
    if (olds.value !== news.value) return { replaces: ["value"] };
    if (olds.ttl !== news.ttl) return { changes: true };
    return { changes: false };
  },
  async update(id, olds, news) {
    const record = await dnsApi.update(id, news);
    return { outs: { ttl: record.ttl } };
  },
  async delete(id) { await dnsApi.delete(id); },
  async read(id, props) {
    const record = await dnsApi.get(props.name);
    return { id, props: record };
  },
};

